// Clean, validate and score each form submission.
const escapeHtml = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all().map(({ json }) => {
  const name = String(json['Name'] ?? '').trim().replace(/\s+/g, ' ');
  const email = String(json['Email'] ?? '').trim().toLowerCase();
  const phone = String(json['Phone'] ?? '').trim() || null;
  const company = String(json['Company'] ?? '').trim() || null;
  const message = String(json['Message'] ?? '').trim();

  const reasons = [];
  if (name.length < 2) reasons.push('name too short');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) reasons.push('invalid email');
  if (message.length < 10) reasons.push('message too short');
  const links = (message.match(/https?:\/\//gi) || []).length;
  if (links > 2) reasons.push('too many links');

  const valid = reasons.length === 0;

  return {
    json: {
      name, email, phone, company, message,
      source: 'n8n-form',
      status: valid ? 'new' : 'spam',
      valid,
      reasons,
      submittedAt: json.submittedAt ?? new Date().toISOString(),
      safe: {
        name: escapeHtml(name),
        email: escapeHtml(email),
        phone: escapeHtml(phone ?? '-'),
        company: escapeHtml(company ?? '-'),
        message: escapeHtml(message.length > 800 ? message.slice(0, 800) + '...' : message),
      },
    },
  };
});

